    do {                                                                                           \
        if ((v).count == (v).capacity)                                                             \
            (v).items = ml_grow((v).items, &(v).capacity, sizeof(*(v).items), (v).count);          \
        (v).items[(v).count++] = (x);                                                              \
    } while (0)
